import { NextResponse } from "next/server";
import { z } from "zod";
import { createServerSupabase } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
const schema=z.object({status:z.enum(["NEW","PREPARING","READY","COMPLETED","CANCELLED"])});
export async function PATCH(request:Request,{params}:{params:Promise<{id:string}>}){try{const {id}=await params;const parsed=schema.safeParse(await request.json());if(!parsed.success)return NextResponse.json({error:"Choose a valid order status."},{status:400});const auth=await createServerSupabase();const {data:{user}}=await auth.auth.getUser();if(!user)return NextResponse.json({error:"Please log in."},{status:401});const db=createAdminClient();const {data:vendor}=await db.from("vendors").select("id").eq("owner_id",user.id).single();if(!vendor)return NextResponse.json({error:"Shop not found."},{status:404});const {data:order}=await db.from("orders").select("id,payment_status,fulfilment_status").eq("id",id).eq("vendor_id",vendor.id).maybeSingle();if(!order)return NextResponse.json({error:"Order not found."},{status:404});if(parsed.data.status!=="NEW"&&parsed.data.status!=="CANCELLED"&&order.payment_status!=="SUCCESS")return NextResponse.json({error:"Only paid orders can move to Preparing, Ready or Completed."},{status:409});const validNext:Record<string,string[]>={NEW:["PREPARING","CANCELLED","NEW"],PREPARING:["READY","CANCELLED","PREPARING"],READY:["COMPLETED","CANCELLED","READY"],COMPLETED:["COMPLETED"],CANCELLED:["CANCELLED"]};if(!validNext[order.fulfilment_status]?.includes(parsed.data.status))return NextResponse.json({error:"That order cannot move to the selected status."},{status:409});const {error}=await db.from("orders").update({fulfilment_status:parsed.data.status}).eq("id",id).eq("vendor_id",vendor.id);if(error)throw error;return NextResponse.json({success:true,status:parsed.data.status});}catch{return NextResponse.json({error:"Order status could not be updated."},{status:503});}}
